import {clock,situation} from './play-model.js';
export const teeTime=id=>clock(510+(id-8)*10);
export function describeGroup(group,groups,minutes,choice='auto',target=245){const tee=teeTime(group.id),scheduled=minutes<(group.id-8)*10,scenario=group.status||situation(minutes*245/target,choice),phase=scheduled?'At first tee':group.fraction<.15?'At the tee':group.fraction>.8?'Near the green':'On the fairway';let pace='On pace',kind='normal',activity=scheduled?'Waiting for tee time':phase==='At the tee'?'Preparing to play':phase==='Near the green'?'Finishing the hole':'Playing the hole';if(scheduled){pace='Starting soon';kind='scheduled';}else if(group.stale){pace='Location uncertain';kind='stale';activity='Last known demo position';}else if(scenario==='queue'&&group.id===4&&group.hole===5){pace='Over hole target';kind='slow';activity='Time on hole exceeds target';}else if(scenario==='queue'){pace=group.waiting?'Waiting behind traffic':'On pace · delay ahead';kind='queue';activity=group.waiting?'Waiting for space ahead':'Playing toward a reported delay';}else if(scenario==='gap'&&group.id===8){pace='Gap ahead';kind='gap';activity='Space available ahead';}const index=groups.findIndex(g=>g.id===group.id),ahead=groups[index-1]||null,behind=groups[index+1]||null;return {tee,label:tee+' tee-time group',hole:group.hole,phase,activity,pace,kind,scheduled,ahead,behind,source:'Demo activity · not GPS zone detection'};}
export function paceGuidance(groups,minutes,choice='auto',target=245){const own=groups.find(g=>g.id===8),context=describeGroup(own,groups,minutes,choice,target);if(context.kind==='stale')return {state:'stale',title:context.tee+' group · tracking paused',message:'The marker is frozen at its last demo observation. Check tracking before making a pace decision.',action:'Check location sharing. No pace warning applies.'};if(context.kind==='queue')return {state:'queue',title:'Delay ahead · hole 5',message:'The 07:50 group has exceeded the hole-5 demo target. Your '+context.tee+' group '+(own.waiting?'is waiting behind traffic':'is still on pace')+'; waiting does not count against your pace.',action:'Keep your place and play when safe. No catch-up alert applies.',incident:own.incident};if(context.kind==='gap')return {state:'gap',title:'A gap is opening ahead · hole '+own.hole,message:context.tee+' group: space is available toward the '+(context.ahead?teeTime(context.ahead.id):'preceding')+' group. Keep contact when safe.',action:'A gentle golfer-first nudge. Staff review is the next planned step if the gap persists.'};return {state:'normal',title:context.tee+' group · on pace',message:'Hole '+own.hole+' · '+context.phase.toLowerCase()+'. Keep comfortable contact with the group ahead when safe.',action:'No action needed. Enjoy the round.'};}
